function rng(seed) { let a = seed >>> 0; return () => { a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const BOARD_CACHE = {};
function makeBoard(n, seed, talkEvery, links) {
  const key = [n, seed, talkEvery, links].join('-');
  if (BOARD_CACHE[key]) return BOARD_CACHE[key];
  const cols = n <= 30 ? 6 : n <= 49 ? 7 : 10, rows = Math.ceil(n / cols);
  const R = rng(seed * 7919 + n), ri = (a, b) => a + Math.floor(R() * (b - a + 1));
  const nl = links || (n <= 30 ? 3 : n <= 49 ? 4 : 8);
  const used = new Set([1, n]), L = [], S = [];
  const row = t => Math.floor((t - 1) / cols);
  const colOf = t => { const r = row(t); let c = (t - 1) % cols; return r % 2 ? cols - 1 - c : c; };
  const span = (n - cols - 2) / nl;
  let g = 0;
  while (L.length < nl && g++ < 800) {
    const lo = Math.max(2, Math.floor(2 + L.length * span)), hi = Math.min(n - cols - 1, Math.floor(2 + (L.length + 1) * span));
    const a = ri(lo, Math.max(lo, hi)), b = a + cols * ri(1, 2) + ri(-1, 1);
    if (b >= n || row(b) <= row(a) || used.has(a) || used.has(b) || Math.abs(colOf(a) - colOf(b)) > 2) continue;
    used.add(a); used.add(b); L.push({ from: a, to: b });
  }
  g = 0;
  while (S.length < nl && g++ < 800) {
    const lo = Math.floor(cols + 2 + S.length * span), hi = Math.min(n - 2, Math.floor(cols + 2 + (S.length + 1) * span));
    const h = ri(lo, Math.max(lo, hi)), t = h - cols * ri(1, 2) - ri(-1, 1);
    if (t < 2 || row(t) >= row(h) || used.has(h) || used.has(t) || Math.abs(colOf(h) - colOf(t)) > 3) continue;
    used.add(h); used.add(t); S.push({ from: h, to: t });
  }
  const heads = new Set(S.map(s => s.from)), talk = [];
  let nx = ri(2, 4);
  for (let t = 2; t < n; t++) {
    if (t < nx || used.has(t) || heads.has(t + 1)) continue; // rule: never a snake head right after a talk tile
    talk.push(t); nx = t + talkEvery + ri(-1, 1);
  }
  const b = { n, cols, rows, L, S, talk: new Set(talk), talkList: talk, used };
  BOARD_CACHE[key] = b; return b;
}
